package com.yosmitha.enterprise_iam.config;
import org.springframework.context.annotation.*;import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.oauth2.server.resource.authentication.*;import io.jsonwebtoken.security.Keys;import javax.crypto.SecretKey;import java.util.Base64;
@Configuration @EnableMethodSecurity public class SecurityConfig {
 @Bean SecurityFilterChain chain(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/swagger-ui/**","/v3/api-docs/**").permitAll().requestMatchers("/api/admin/**").hasRole("ADMIN").anyRequest().authenticated()).oauth2ResourceServer(o->o.jwt(j->j.jwtAuthenticationConverter(converter()))).build();}
 @Bean JwtDecoder decoder(@org.springframework.beans.factory.annotation.Value("${app.jwt.secret}")String s){SecretKey k=Keys.hmacShaKeyFor(Base64.getDecoder().decode(s));return NimbusJwtDecoder.withSecretKey(k).build();}
 @Bean JwtAuthenticationConverter converter(){JwtGrantedAuthoritiesConverter c=new JwtGrantedAuthoritiesConverter();c.setAuthoritiesClaimName("authorities");c.setAuthorityPrefix("");JwtAuthenticationConverter x=new JwtAuthenticationConverter();x.setJwtGrantedAuthoritiesConverter(c);return x;}
}
